{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Clinafloxacin, the closest structural analogue, had an absolute bioavailability of 0.876 in pooled Phase I-III human data, directly supporting high oral bioavailability for this fluoroquinolone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Clinafloxacin absolute oral bioavailability was approximately 90% versus intravenous dosing in volunteers, providing direct high-bioavailability evidence from the most transferable analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Ofloxacin, a closely related fluoroquinolone, showed an estimated absolute oral bioavailability of 91% in patients, supporting high absorption for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Levofloxacin tablets had a mean absolute bioavailability of at least 99% in healthy volunteers, confirming near-complete oral absorption in a structurally related fluoroquinolone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Moxifloxacin had a mean absolute oral bioavailability of 92% in healthy volunteers, further supporting consistently high fluoroquinolone oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone antibiotic with the same 4-quinolone-3-carboxylic acid core and 7-amino substituent pattern as many fluoroquinolones with experimentally confirmed high oral bioavailability. The closest analogue, clinafloxacin, shows absolute bioavailability around 88-90%, and other close analogues such as ofloxacin, levofloxacin, and moxifloxacin show 90-100% oral bioavailability. No evidence suggests a low-bioavailability liability for this scaffold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The query-specific spirocyclic amine and 2-fluorocyclopropyl substituents are not represented by an identical analogue, though they are consistent with highly absorbed fluoroquinolone structures."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

